result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "ini.py", "content": """"Minimal INI parser, stdlib only (no configparser).

Grammar:
    [section]          -- section header
    key = value        -- key/value pair
    ; or # at line start (after whitespace) -- full-line comment

Values may be wrapped in single or double quotes; the quotes are stripped.
Inside double quotes the escapes \\n and \\t are honored. Keys appearing
before any section header belong to the implicit "DEFAULT" section, which is
always present in the result.
"""

__all__ = ["IniError", "DuplicateKeyError", "parse"]

DEFAULT_SECTION = "DEFAULT"


class IniError(Exception):
    """A syntax error in the INI text, located by 1-based line and column."""

    def __init__(self, message: str, line: int, column: int):
        super().__init__(f"line {line}, column {column}: {message}")
        self.message = message
        self.line = line
        self.column = column


class DuplicateKeyError(IniError):
    """The same key was assigned twice within one section."""

    def __init__(self, section: str, key: str, line: int, column: int):
        super().__init__(
            f"duplicate key {key!r} in section [{section}]", line, column
        )
        self.section = section
        self.key = key


def _unquote_double(inner: str) -> str:
    out = []
    i = 0
    while i < len(inner):
        ch = inner[i]
        if ch == "\\" and i + 1 < len(inner) and inner[i + 1] in ("n", "t"):
            out.append("\n" if inner[i + 1] == "n" else "\t")
            i += 2
        else:
            out.append(ch)
            i += 1
    return "".join(out)


def _parse_value(raw_value: str, line: int, col_offset: int) -> str:
    value = raw_value.strip()
    if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
        if value[0] == '"':
            return _unquote_double(value[1:-1])
        return value[1:-1]
    if value[:1] in ('"', "'"):
        # Opening quote without a matching closing quote on the same line.
        raise IniError("unterminated quoted value", line, col_offset + 1)
    return value


def parse(text: str) -> dict[str, dict[str, str]]:
    result: dict[str, dict[str, str]] = {DEFAULT_SECTION: {}}
    current = result[DEFAULT_SECTION]

    for lineno, raw in enumerate(text.splitlines(), start=1):
        indent = len(raw) - len(raw.lstrip())
        line = raw.strip()

        if not line or line[0] in ";#":
            continue  # blank line or full-line comment

        if line[0] == "[":
            if not line.endswith("]") or len(line) < 3:
                raise IniError(
                    "malformed section header", lineno, indent + max(len(line), 1)
                )
            name = line[1:-1].strip()
            if not name:
                raise IniError("empty section name", lineno, indent + 2)
            current = result.setdefault(name, {})
            continue

        eq = line.find("=")
        if eq == -1:
            raise IniError(
                f"expected 'key = value', got {line!r}",
                lineno,
                indent + max(len(line), 1),
            )
        key = line[:eq].strip()
        if not key:
            raise IniError("empty key before '='", lineno, indent + 1)

        value_col = indent + line.index("=", eq - (eq - line.index("="))) if False else None
        if key in current:
            raise DuplicateKeyError(
                _current_name(result, current), key, lineno, indent + 1
            )
        current[key] = _parse_value(line[eq + 1:], lineno, indent + eq + 2)

    return result


def _current_name(
    result: dict[str, dict[str, str]], section: dict[str, str]
) -> str:
    for name, table in result.items():
        if table is section:
            return name
    return DEFAULT_SECTION
